eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   getProjectBySlug: () => (/* binding */ getProjectBySlug),\n/* harmony export */   projectsData: () => (/* binding */ projectsData)\n/* harmony export */ });\nconst projectsData = [\n    {\n        slug: \"repuestos-jmd\",\n        titleEs: \"Repuestos JMD\",\n        titleEn: \"JMD Spare Parts\",\n        descriptionEs: \"E-commerce full-stack para repuestos de veh\\xedculos chinos en Costa Rica, con panel admin, cat\\xe1logo din\\xe1mico y sistema de \\xf3rdenes con emails autom\\xe1ticos.\",\n        descriptionEn: \"Full-stack e-commerce for Chinese vehicle spare parts in Costa Rica, featuring an admin panel, dynamic catalog and order system with automated emails.\",\n        longDescEs: \"Dise\\xf1o y desarrollo completo de Repuestos JMD, una tienda en l\\xednea especializada en repuestos para veh\\xedculos de marcas chinas (BYD, Geely, Chery, Changan, GWM, Wuling, Jetour) en Costa Rica. Construida con Next.js 14 App Router, TypeScript y Tailwind CSS, con despliegue continuo en Vercel desde GitHub. El frontend presenta un dise\\xf1o oscuro profesional con hero carousel animado, mega men\\xfa de navegaci\\xf3n con categor\\xedas, carrusel infinito tipo cinta con CSS keyframes, cards con efecto glow reactivo al mouse y sistema de paginaci\\xf3n con selector 10/25/50/100 por p\\xe1gina. El cat\\xe1logo cuenta con filtros independientes por marca, modelo, categor\\xeda y rango de precio, donde el sidebar de filtros tiene scroll aut\\xf3nomo preservando sus bordes redondeados. El carrito de compras (sin login, localStorage) incluye breakdown detallado con IVA 13%, estimado de env\\xedo y campo de c\\xf3digo promocional. Las \\xf3rdenes se guardan en Supabase y disparan emails autom\\xe1ticos tanto al cliente como al administrador mediante Resend. El panel de administraci\\xf3n (protegido por Supabase Auth) ofrece CRUD completo para productos, categor\\xedas, marcas y modelos, con carga de im\\xe1genes por drag-and-drop directo a Supabase Storage. El sistema i18n ES/EN y el selector de moneda CRC/USD con tipo de cambio en tiempo real completan la experiencia. La base de datos PostgreSQL en Supabase incluye compatibilidades por modelo de veh\\xedculo, permitiendo filtrar qu\\xe9 piezas sirven para qu\\xe9 auto espec\\xedfico.\",\n        longDescEn: \"Full design and development of Repuestos JMD, an online store specialized in spare parts for Chinese brand vehicles (BYD, Geely, Chery, Changan, GWM, Wuling, Jetour) in Costa Rica. Built with Next.js 14 App Router, TypeScript and Tailwind CSS, with continuous deployment on Vercel from GitHub. The frontend features a professional dark design with animated hero carousel, category mega menu navigation, infinite CSS keyframes marquee ribbon, mouse-reactive glow cards and a pagination system with 10/25/50/100 per page selector. The catalog includes independent filters by brand, model, category and price range, with a sidebar that scrolls autonomously while preserving its rounded corners. The shopping cart (no login required, localStorage) includes a detailed breakdown with 13% VAT, shipping estimate and promo code input. Orders are saved to Supabase and trigger automatic emails to both client and admin via Resend. The admin panel (protected by Supabase Auth) provides full CRUD for products, categories, brands and models, with drag-and-drop image upload directly to Supabase Storage. ES/EN i18n and CRC/USD currency selector with real-time exchange rate complete the experience. The PostgreSQL database in Supabase includes vehicle model compatibility tables, enabling filtering of which parts fit which specific car.\",\n        tags: [\n            \"Next.js 14\",\n            \"TypeScript\",\n            \"Tailwind CSS\",\n            \"Supabase\",\n            \"PostgreSQL\",\n            \"Supabase Auth\",\n            \"Supabase Storage\",\n            \"Resend\",\n            \"Vercel\",\n            \"React Context\",\n            \"E-commerce\",\n            \"CRUD\",\n            \"i18n\",\n            \"App Router\"\n        ],\n        images: [\n            \"/Images/Projects/Repuestos-JMD/image-1.png\",\n            \"/Images/Projects/Repuestos-JMD/image-2.png\",\n            \"/Images/Projects/Repuestos-JMD/image-3.png\",\n            \"/Images/Projects/Repuestos-JMD/image-4.png\"\n        ],\n        demoUrl: \"https://repuestos-jmd.vercel.app\",\n        codeUrl: \"https://github.com/Diego2452/Repuestos-JMD\",\n        year: \"2026\",\n        client: \"JMD Repuestos\"\n    },\n    {\n        slug: \"sysrrhh-mideplan\",\n        titleEs: \"SYSRRHH — Instituci\\xf3n Gubernamental\",\n        titleEn: \"SYSRRHH — Government Institution\",\n        descriptionEs: \"Sistema institucional de Gesti\\xf3n de Recursos Humanos para una instituci\\xf3n gubernamental de Costa Rica, desarrollado con Laravel 12, PHP 8.5 y MySQL.\",\n        descriptionEn: \"Institutional Human Resources Management System for a Costa Rican government institution, built with Laravel 12, PHP 8.5 and MySQL.\",\n        longDescEs: \"Desarrollo del Sistema de Gesti\\xf3n de Recursos Humanos (SYSRRHH) para una instituci\\xf3n gubernamental de Costa Rica, en el marco de la Pr\\xe1ctica Universitaria Supervisada de la Universidad Fidelitas. El sistema fue construido con Laravel 12, PHP 8.5, MySQL y Bootstrap AdminLTE, siguiendo una arquitectura estricta de procedimientos almacenados sin Eloquent, control de versiones con SVN y autenticaci\\xf3n mediante Active Directory LDAP institucional. Comprende m\\xf3dulos de Marcas y Asistencia con justificaciones individuales y masivas, Gesti\\xf3n de Per\\xedodos y Saldos de Vacaciones con bit\\xe1cora de ajustes y anexos, Vacaciones Colectivas con descuento masivo mediante cursor SQL, Reportes institucionales incluyendo un reporte PIVOT din\\xe1mico de Art. 51 con detecci\\xf3n de columnas en runtime, panel de Estad\\xedsticas, Bit\\xe1cora de Ingresos al Sistema y dashboards diferenciados por rol. La identidad visual fue estandarizada con la paleta institucional del cliente, widget de accesibilidad con alto contraste, escala de grises e inversi\\xf3n de colores, men\\xfa lateral con \\xe1rbol CSS puro de 3 niveles, \\xedconos Bootstrap Icons sem\\xe1nticamente coherentes por m\\xf3dulo y sistema de permisos granular por rol con soporte de jerarqu\\xeda padre-hijo-nieto.\",\n        longDescEn: \"Development of the Human Resources Management System (SYSRRHH) for a Costa Rican government institution, as part of the Universidad Fidelitas Supervised University Internship. Built with Laravel 12, PHP 8.5, MySQL and Bootstrap AdminLTE, following a strict stored procedure architecture without Eloquent, SVN version control and institutional LDAP Active Directory authentication. The system includes modules for Attendance Tracking with individual and bulk justifications, Vacation Period and Balance Management with adjustment logs and attachments, Collective Vacations with bulk deduction via SQL cursor, institutional Reports including a dynamic PIVOT report for Art. 51 with runtime column detection, Statistics dashboard, System Access Log and role-differentiated dashboards. The visual identity was standardized with the MIDEPLAN institutional palette, an accessibility widget with high contrast, grayscale and color inversion, a 3-level pure CSS sidebar tree, semantically coherent Bootstrap Icons per module and a granular role-based permission system with parent-child-grandchild hierarchy support.\",\n        tags: [\n            \"Laravel 12\",\n            \"PHP 8.5\",\n            \"MySQL\",\n            \"Bootstrap\",\n            \"AdminLTE\",\n            \"jQuery\",\n            \"DataTables\",\n            \"Select2\",\n            \"Blade\",\n            \"SVN\",\n            \"LDAP\",\n            \"Active Directory\",\n            \"Stored Procedures\",\n            \"SweetAlert2\",\n            \"Bootstrap Icons\"\n        ],\n        images: [\n            \"/Images/Projects/MIDEPLAN-Sysrrhh/image-1.png\",\n            \"/Images/Projects/MIDEPLAN-Sysrrhh/image-2.png\",\n            \"/Images/Projects/MIDEPLAN-Sysrrhh/image-3.png\",\n            \"/Images/Projects/MIDEPLAN-Sysrrhh/image-4.png\"\n        ],\n        demoUrl: \"#\",\n        codeUrl: \"#\",\n        year: \"2026\",\n        client: \"Government Institution — Costa Rica\"\n    },\n    {\n        slug: \"proweb-solutions-next.js\",\n        titleEs: \"PROWEB Solutions Beta\",\n        titleEn: \"PROWEB Solutions Beta\",\n        descriptionEs: \"Versi\\xf3n actual del portafolio, construida desde cero con Next.js, TypeScript, Tailwind CSS y Framer Motion.\",\n        descriptionEn: \"Current portfolio version, built from scratch with Next.js, TypeScript, Tailwind CSS and Framer Motion.\",\n        longDescEs: \"La versi\\xf3n Beta de PROWEB Solutions es la versi\\xf3n actual, construida completamente desde cero en Visual Studio Code. Implementa Next.js con App Router, TypeScript, Tailwind CSS y Framer Motion. Incluye animaciones avanzadas con part\\xedculas interactivas en canvas, efectos 3D en tarjetas al pasar el mouse, sistema de traducci\\xf3n ES/EN, typewriter animado en el hero, navbar responsiva con men\\xfa mobile, p\\xe1ginas de detalle por proyecto con carrusel de im\\xe1genes y un dise\\xf1o oscuro profesional de alto nivel — demostrando verdadera experiencia en desarrollo web moderno desde cero.\",\n        longDescEn: \"The Beta version of PROWEB Solutions is the current version, built entirely from scratch in Visual Studio Code. It uses Next.js with App Router, TypeScript, Tailwind CSS and Framer Motion. It includes advanced animations with interactive canvas particles, 3D card tilt effects on hover, an ES/EN translation system, animated typewriter in the hero, responsive navbar with mobile menu, per-project detail pages with image carousel and a high-quality professional dark design — demonstrating real expertise in modern web development from scratch.\",\n        tags: [\n            \"Next.js\",\n            \"TypeScript\",\n            \"Tailwind CSS\",\n            \"Framer Motion\",\n            \"React\",\n            \"Vercel\",\n            \"VS Code\"\n        ],\n        images: [\n            \"/Images/Projects/PROWEB-Solutions/image-1.png\",\n            \"/Images/Projects/PROWEB-Solutions/image-2.png\",\n            \"/Images/Projects/PROWEB-Solutions/image-3.png\",\n            \"/Images/Projects/PROWEB-Solutions/image-4.png\"\n        ],\n        demoUrl: \"https://prowebsolutionscr.netlify.app\",\n        codeUrl: \"https://github.com/Diego2452/PROWEB-Solutions\",\n        year: \"2025\",\n        client: \"PROWEB Solutions\"\n    },\n    {\n        slug: \"grac-app\",\n        titleEs: \"GRAC App\",\n        titleEn: \"GRAC App\",\n        descriptionEs: \"Aplicaci\\xf3n m\\xf3vil APK desarrollada para una instituci\\xf3n municipal, creada con FlutterFlow, Flutter y Firebase.\",\n        descriptionEn: \"APK mobile application developed for a municipal institution, built with FlutterFlow, Flutter and Firebase.\",\n        longDescEs: \"Desarrollo de la GRAC App (Gesti\\xf3n de Reportes y Actividades Comunitarias), una aplicaci\\xf3n m\\xf3vil en formato APK para una instituci\\xf3n municipal, creada con FlutterFlow utilizando Flutter y Dart, e integrada con Firebase y Cloud Firestore de Google. La aplicaci\\xf3n fue dise\\xf1ada para centralizar informaci\\xf3n y mejorar la comunicaci\\xf3n institucional, con una arquitectura orientada a escalabilidad, gesti\\xf3n de datos en la nube y despliegue funcional en dispositivos Android. Se implement\\xf3 autenticaci\\xf3n de usuarios mediante Firebase Auth y sincronizaci\\xf3n en tiempo real con Cloud Firestore.\",\n        longDescEn: \"Development of the GRAC App (Community Reports and Activities Management), an APK mobile application for a municipal institution, built with FlutterFlow using Flutter and Dart, integrated with Google Firebase and Cloud Firestore. The app was designed to centralize information and improve institutional communication, with an architecture focused on scalability, cloud data management and functional deployment on Android devices. Firebase Auth was implemented for user authentication and real-time sync with Cloud Firestore.\",\n        tags: [\n            \"FlutterFlow\",\n            \"Flutter\",\n            \"Dart\",\n            \"Firebase\",\n            \"Cloud Firestore\",\n            \"Firebase Auth\",\n            \"Android\"\n        ],\n        images: [\n            \"/Images/Projects/GRAC-App/image-1.png\",\n            \"/Images/Projects/GRAC-App/image-2.png\",\n            \"/Images/Projects/GRAC-App/image-3.png\",\n            \"/Images/Projects/GRAC-App/image-4.png\"\n        ],\n        demoUrl: \"https://app.flutterflow.io/share/app-movil-gestion-reportes-actividades-comunitarias-distrito-zapote-r5irg2\",\n        codeUrl: \"#\",\n        year: \"2024\",\n        client: \"Municipal Institution\"\n    },\n    {\n        slug: \"restaurante-el-varon\",\n        titleEs: 'Restaurante \"El Var\\xf3n\"',\n        titleEn: '\"El Var\\xf3n\" Restaurant',\n        descriptionEs: \"Sistema integral para restaurante con .NET Framework, ASP.NET MVC, SQL Server y despliegue en Azure Web Apps.\",\n        descriptionEn: \"Full restaurant management system with .NET Framework, ASP.NET MVC, SQL Server and Azure Web Apps deployment.\",\n        longDescEs: \"Desarrollo de un sistema integral para El Var\\xf3n Restaurante utilizando .NET Framework y .NET Core en Visual Studio 2022, orientado al manejo completo de las operaciones del restaurante. El proyecto implement\\xf3 una arquitectura Model–View–Controller (MVC) para el desarrollo de p\\xe1ginas web din\\xe1micas, l\\xf3gica de negocio y gesti\\xf3n de datos, con conexi\\xf3n ASP.NET a una base de datos SQL Server administrada desde MySQL Workbench y phpMyAdmin. La aplicaci\\xf3n fue publicada en Azure Web Apps (azurewebsites), abarcando configuraci\\xf3n de entorno, despliegue en la nube y comunicaci\\xf3n segura con la base de datos. El frontend fue construido con Bootstrap para garantizar responsividad, priorizando un enfoque basado en c\\xf3digo sin uso de constructores visuales.\",\n        longDescEn: \"Development of a full management system for El Var\\xf3n Restaurant using .NET Framework and .NET Core in Visual Studio 2022, covering all restaurant operations. The project implemented a Model–View–Controller (MVC) architecture for dynamic web pages, business logic and data management, with ASP.NET connected to a SQL Server database managed through MySQL Workbench and phpMyAdmin. The application was published on Azure Web Apps, covering environment setup, cloud deployment and secure database communication. The frontend was built with Bootstrap to ensure responsiveness, prioritizing a code-first approach without visual page builders.\",\n        tags: [\n            \".NET Framework\",\n            \".NET Core\",\n            \"ASP.NET MVC\",\n            \"C#\",\n            \"SQL Server\",\n            \"MySQL Workbench\",\n            \"phpMyAdmin\",\n            \"Bootstrap\",\n            \"Azure Web Apps\",\n            \"Visual Studio 2022\"\n        ],\n        images: [\n            \"/Images/Projects/El-Varon/image-1.png\",\n            \"/Images/Projects/El-Varon/image-2.png\",\n            \"/Images/Projects/El-Varon/image-3.png\",\n            \"/Images/Projects/El-Varon/image-4.png\"\n        ],\n        demoUrl: \"#\",\n        codeUrl: \"https://github.com/WakoSD/ElVaron_Proyecto\",\n        year: \"2024\",\n        client: \"Restaurante El Var\\xf3n\"\n    },\n    {\n        slug: \"construxion-arq-nextjs\",\n        titleEs: \"ConstruxionArq – Next.js\",\n        titleEn: \"ConstruxionArq – Next.js\",\n        descriptionEs: \"Migraci\\xf3n completa de WordPress a Next.js 14 con deploy autom\\xe1tico v\\xeda GitHub Actions y soporte biling\\xfce ES/EN.\",\n        descriptionEn: \"Full migration from WordPress to Next.js 14 with automated CI/CD via GitHub Actions and bilingual ES/EN support.\",\n        longDescEs: \"Migraci\\xf3n completa del sitio corporativo de una firma de arquitectura costarricense desde WordPress/Elementor hacia un stack moderno en Next.js 14 con TypeScript y Tailwind CSS. El sitio se exporta como HTML est\\xe1tico y se despliega autom\\xe1ticamente en SiteGround mediante GitHub Actions + FTP Deploy cada vez que se hace un push a main. Se implement\\xf3 un sistema de internacionalizaci\\xf3n propio (sin librer\\xedas externas) con React Context que permite cambiar entre espa\\xf1ol e ingl\\xe9s en tiempo real y persiste la preferencia en localStorage. La galer\\xeda de proyectos incluye 19 proyectos con im\\xe1genes reales rescatadas del WordPress original, lightbox, b\\xfasqueda con filtros y paginaci\\xf3n. El dise\\xf1o replica fielmente la identidad corporativa del cliente con video hero, animaciones reveal por IntersectionObserver y cursor personalizado.\",\n        longDescEn: \"Full migration of a Costa Rican architecture firm's corporate website from WordPress/Elementor to a modern stack using Next.js 14, TypeScript and Tailwind CSS. The site exports as static HTML and deploys automatically to SiteGround via GitHub Actions + FTP Deploy on every push to main. A custom internationalization system was built using React Context (no external libraries) allowing real-time switching between Spanish and English with localStorage persistence. The project gallery features 19 projects with real images rescued from the original WordPress, including a lightbox, search with filters and pagination. The design faithfully replicates the client's corporate identity with a hero video, IntersectionObserver reveal animations and a custom cursor.\",\n        tags: [\n            \"Next.js 14\",\n            \"TypeScript\",\n            \"Tailwind CSS\",\n            \"GitHub Actions\",\n            \"SiteGround\",\n            \"i18n\",\n            \"CI/CD\"\n        ],\n        images: [\n            \"/Images/Projects/ConstruxionARQ-New/image-1.png\",\n            \"/Images/Projects/ConstruxionARQ-New/image-2.png\",\n            \"/Images/Projects/ConstruxionARQ-New/image-3.png\",\n            \"/Images/Projects/ConstruxionARQ-New/image-4.png\"\n        ],\n        demoUrl: \"https://construxionarq.com\",\n        codeUrl: \"https://github.com/Diego2452/ConstruxionARQ\",\n        year: \"2025\",\n        client: \"ConstruxionArq\"\n    },\n    {\n        slug: \"construxion-arq-wordpress\",\n        titleEs: \"ConstruxionArq – WordPress\",\n        titleEn: \"ConstruxionArq – WordPress\",\n        descriptionEs: \"Sitio corporativo para firma de arquitectura costarricense con WordPress, Elementor y SiteGround. Posteriormente migrado a Next.js 14.\",\n        descriptionEn: \"Corporate site for a Costa Rican architecture firm built with WordPress, Elementor and SiteGround. Later migrated to Next.js 14.\",\n        longDescEs: \"Se desarroll\\xf3 un sitio web corporativo para una firma de arquitectura utilizando WordPress y SiteGround, enfocado en una estructura clara y f\\xe1cil de administrar. El sitio incluye secciones de inicio, proyectos, acerca de y contacto, con integraci\\xf3n del plugin GTranslate para contenido biling\\xfce espa\\xf1ol/ingl\\xe9s. El dise\\xf1o fue construido con Elementor sobre el tema Blocksy, logrando una interfaz visual, responsiva y alineada con la identidad corporativa del cliente. El portafolio de proyectos fue gestionado mediante Custom Post Types con galer\\xedas Swiper integradas. Este sitio fue posteriormente migrado a Next.js 14 como parte de una modernizaci\\xf3n del stack.\",\n        longDescEn: \"A corporate website was developed for an architecture firm using WordPress and SiteGround, focused on a clear and easy-to-manage structure. The site includes home, projects, about and contact sections, with GTranslate plugin integration for Spanish/English bilingual content. The design was built with Elementor on the Blocksy theme, delivering a visual, responsive interface aligned with the client's corporate identity. The project portfolio was managed through Custom Post Types with integrated Swiper galleries. This site was later migrated to Next.js 14 as part of a stack modernization.\",\n        tags: [\n            \"WordPress\",\n            \"Elementor\",\n            \"Blocksy\",\n            \"SiteGround\",\n            \"PHP\",\n            \"CSS\",\n            \"GTranslate\"\n        ],\n        images: [\n            \"/Images/Projects/ConstruxionARQ-Old/image-1.png\",\n            \"/Images/Projects/ConstruxionARQ-Old/image-2.png\",\n            \"/Images/Projects/ConstruxionARQ-Old/image-3.png\",\n            \"/Images/Projects/ConstruxionARQ-Old/image-4.png\"\n        ],\n        demoUrl: \"#\",\n        codeUrl: \"#\",\n        year: \"2023\",\n        client: \"ConstruxionArq\"\n    },\n    {\n        slug: \"proweb-solutions-squarespace\",\n        titleEs: \"PROWEB Solutions Alpha\",\n        titleEn: \"PROWEB Solutions Alpha\",\n        descriptionEs: \"Primera versi\\xf3n del portafolio corporativo, desarrollada en Squarespace con dominio .com propio.\",\n        descriptionEn: \"First version of the corporate portfolio, built on Squarespace with a custom .com domain.\",\n        longDescEs: \"La versi\\xf3n Alpha de PROWEB Solutions fue la primera presencia digital oficial de la empresa. Fue montada en Squarespace, incluyendo la adquisici\\xf3n y configuraci\\xf3n de un dominio .com. El proyecto abarc\\xf3 la personalizaci\\xf3n completa del dise\\xf1o mediante las herramientas nativas de la plataforma, estructuraci\\xf3n del contenido, adaptaci\\xf3n visual a una identidad corporativa moderna y optimizaci\\xf3n para distintos dispositivos — demostrando capacidad para entregar soluciones web r\\xe1pidas, funcionales y profesionales sin necesidad de c\\xf3digo.\",\n        longDescEn: \"The Alpha version of PROWEB Solutions was the company's first official digital presence. It was built on Squarespace, including the acquisition and configuration of a .com domain. The project covered full design customization using the platform's native tools, content structuring, visual adaptation to a modern corporate identity and optimization for different devices — demonstrating the ability to deliver fast, functional and professional web solutions without code.\",\n        tags: [\n            \"Squarespace\",\n            \"CSS\",\n            \"Domain .com\"\n        ],\n        images: [\n            \"/Images/Projects/PROWEB-Solutions-Old/image-1.png\",\n            \"/Images/Projects/PROWEB-Solutions-Old/image-2.png\",\n            \"/Images/Projects/PROWEB-Solutions-Old/image-3.png\",\n            \"/Images/Projects/PROWEB-Solutions-Old/image-4.png\"\n        ],\n        demoUrl: \"https://prowebsolutionscr.com\",\n        codeUrl: \"#\",\n        year: \"2024\",\n        client: \"PROWEB Solutions\"\n    }\n];\nfunction getProjectBySlug(slug) {\n    return projectsData.find((p)=>p.slug === slug);\n}\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/lib/projectsData.ts\n");

